// Generates docs/process-map.md and docs/import.md from the code, so docs cannot drift.
// Run: npm run docs
import { writeFileSync, mkdirSync } from "node:fs";
import ExcelJS from "exceljs";
import { PROCESS_MERMAID, PROCESS_NOTES } from "../src/lib/process-map";
import { IMPORT_FIELDS, IGNORED_HEADERS } from "../src/lib/import/mapping";
import { SHEET_COLUMNS, EXTRA_COLUMNS, type SheetKey } from "../src/lib/nnr-sheet";

mkdirSync("docs", { recursive: true });

writeFileSync(
  "docs/process-map.md",
  `# Export process map

<!-- Generated by \`npm run docs\` from src/lib/process-map.ts. Do not edit by hand. -->

Ocean export flow at NNR Global Logistics, from booking request to arrival. Also shown in the app at \`/process\`.
Italic labels are the shipment status after each step.

\`\`\`mermaid
${PROCESS_MERMAID}
\`\`\`

${PROCESS_NOTES.map((n) => `- ${n}`).join("\n")}
`,
);

const rows = IMPORT_FIELDS.map((f) => {
  const headers = f.headers.map((h) => `\`${h}\``).join(", ");
  const req = "required" in f && f.required ? "yes" : "";
  const note = "note" in f ? f.note : "";
  return `| ${f.key} | ${headers} | ${req} | ${note} |`;
}).join("\n");

// How each column of NNR's monitoring sheet is read (Record<SheetKey> so a new column can't be left out).
const SHEET_READ: Record<SheetKey, string> = {
  hbl: "Kept as the HBL No. `DIRECT BL` = no HBL (shipping line's own BL). `NNRMNL…F7003 / PART OF 7002` = split shipment, linked to HBL 7002.",
  booking: "Shipping line booking no.",
  shipper: "Matched ignoring spaces and punctuation; spellings one typo apart are merged into the most used one (listed after the check).",
  destination: "Required. The 3-letter HBL code comes from the HBL No., else from the city name.",
  etd: "Date", atd: "Date (makes the shipment DEPARTED)", eta: "Date", ata: "Date (makes it ARRIVED)",
  fcl40: "`1X40'HC & 1X40ST`, `2X40`…", fcl20: "`2X20`…",
  lcl: "`3 PALLETS`, `27 CTS`, `1 WOODEN BOX`… (FCL and LCL on one row is an error)",
  reqPickup: "Date; `TBA` = not set yet", actualPickup: "Date",
  fsiCutoff: "Date & time, e.g. `11 OCT @ 1200H`", preadviseCutoff: "Date & time",
  arrastreCutoff: "Date & time; `N/A` = shipper pays arrastre",
  declShipper: "Filled (not `N/A`) = declaration c/o shipper; a date = filed on that date.",
  declNnr: "A date = filed on that date. `C/O NNR (AAI)` = pending, filed by NNR through forwarder AAI.",
  bocUpload: "Date; `c/o shipper` is kept in remarks", arrastrePaid: "Date; `N/A` here or in the arrastre cut-off = shipper pays",
  docsSent: "Date sent to customer", docsToOverseas: "Date sent to the overseas office",
  carrier: "Shipping line or co-loader name", remarks: "Kept. `CANCELLED` in remarks = cancelled shipment.",
};
const sheetRows = SHEET_COLUMNS.map((c, i) => {
  const name = c.header.filter(Boolean).join(" / ");
  return `| ${String.fromCharCode(65 + i)} | ${name} | ${SHEET_READ[c.key]} |`;
}).join("\n");

writeFileSync(
  "docs/import.md",
  `# Spreadsheet import

<!-- Generated by \`npm run docs\` from src/lib/nnr-sheet.ts and src/lib/import/mapping.ts. Do not edit by hand. -->

Supervisors import the existing monitoring spreadsheet at **Import** (\`/admin/import\`), as \`.xlsx\` or \`.csv\`.
Two layouts are recognised automatically:

1. **NNR's monitoring sheet** (3 header rows, columns A–X below). The app's own raw Excel export uses
   the same layout, plus app columns after a blank column, so an export can be re-imported.
2. **The one-row template** (\`docs/import-template.xlsx\`, headers further down).

## How it works

1. Upload with **Check only** ticked: nothing is saved; you see how many rows are valid and every problem.
2. Untick it and import: valid rows become shipments (source \`IMPORT\`), invalid rows are listed with the reason.
3. Download **rows to fix** (same layout as your upload, with \`ERROR\` and \`ORIGINAL ROW\` columns at the end),
   correct them and upload that file. Rows already imported are skipped (same HBL No., Job No. or old
   booking no.; rows without any number by shipper + destination + pick-up + cargo), so re-uploading is safe.

## Options

- **History cut-off** (default: 30 days ago). Rows whose booking date (ATD, else ETD, else pick-up) is before it are imported as
  **Closed history**: kept for search and volume reports, but no alerts and no on-time scoring
  (the old sheet doesn't record when FSI or pre-advise were actually done). Leave empty to import every row as live.
- **Start year.** The sheet's dates have no year (\`04-Apr\`). Rows are in booking order, so each date takes the
  year nearest to the row before it. The first row's year is guessed so that no date ends up more than
  120 days in the future; set it yourself if the guess is wrong (the check shows the year used).
- **Merge similar shipper names** (on by default): see the shipper column below.
- **Add shippers**: create shippers not in the app yet.

## NNR monitoring sheet columns

| Col | Header | How it is read |
|---|---|---|
${sheetRows}

App columns after the blank column (in the app's export): ${EXTRA_COLUMNS.map((c) => "`" + c.header + "`").join(", ")}.
\`CS EMAIL\` (or \`ASSIGNED CS\`) sets the assigned CS; otherwise it is the person importing.

Dates are read as Asia/Manila time. Accepted: \`04-Apr\`, \`11 OCT @ 1200H\`, \`15-16 MAY\` (first day),
real Excel dates. \`TBA\`, \`N/A\`, \`-\` are blank. Slash dates like \`10/11\` are rejected (day/month order is ambiguous).

## One-row template

The first row must use the headers below (any one spelling per field; case, spaces and punctuation are ignored).


| Field | Accepted headers | Required | Notes |
|---|---|---|---|
${rows}

Ignored on purpose (calculated by the app): ${IGNORED_HEADERS.map((h) => `\`${h}\``).join(", ")}.

## Values

- **Dates:** real Excel date cells, or text \`16-Oct-2026 09:00\` / \`2026-10-16 09:00\`, read as Asia/Manila time.
  Slash dates such as \`10/11/2026\` are rejected because day/month order is ambiguous.
- **Shipment date for reports:** the earliest of requested pick-up, FSI cut-off and ETD, so old shipments
  count in their own month. New Job Nos. use that month too.
- **Status** is recalculated from the dates (e.g. an ATD makes it DEPARTED); only "Cancelled" and "Closed" are read.
- **Arrastre Paid** on imported rows needs no proof file (old records); new payments in the app still require proof.
- Every row is checked with the same rules as the shipment form (e.g. ETA after ETD, FCL needs containers),
  plus: ATA needs ATD, arrastre cannot be paid by NNR when the shipper pays.
- Max ${5000} rows per file.
`,
);

// Template with the preferred header spelling and two example rows.
async function template() {
  const wb = new ExcelJS.Workbook();
  const ws = wb.addWorksheet("Monitoring");
  ws.addRow(IMPORT_FIELDS.map((f) => f.headers[0]));
  ws.getRow(1).font = { bold: true };
  const example: Record<string, string> = {
    jobNo: "", hblNo: "", shipper: "Luzon Coco Products Inc.", destination: "USLAX Los Angeles", pod: "USLGB Long Beach",
    cargo: "2x40HC + 1x20", carrier: "Maersk", bookingRef: "MAEU240001", requestedPickup: "20-Oct-2026 09:00",
    fsiCutoff: "22-Oct-2026 17:00", preadviseCutoff: "23-Oct-2026 12:00", etd: "25-Oct-2026 08:00", arrastreBy: "NNR", cs: "cs1@nnr.test",
  };
  const lcl: Record<string, string> = {
    jobNo: "B-1234", shipper: "Pinoy Dried Mango Co.", destination: "SGSIN Singapore", cargo: "LCL 6 PALLET",
    requestedPickup: "2026-10-21 10:00", declaration: "FILED", arrastreBy: "SHIPPER", remarks: "Old booking from the spreadsheet",
  };
  for (const r of [example, lcl]) ws.addRow(IMPORT_FIELDS.map((f) => r[f.key] ?? ""));
  ws.columns.forEach((c) => (c.width = 20));
  await wb.xlsx.writeFile("docs/import-template.xlsx");
}

template().then(() => console.log("Wrote docs/process-map.md, docs/import.md and docs/import-template.xlsx"));
